import type {Icon} from '@primer/octicons-react'
import {ShieldCheckIcon, ShieldIcon, TrashIcon} from '@primer/octicons-react'
import {Heading, IconButton, RelativeTime} from '@primer/react'
import {Tooltip} from '@primer/react/deprecated'
import {clsx} from 'clsx'

import styles from './DeleteConfigurationListItem.module.css'

interface DeleteConfigurationButtonProps {
  defaultIcon: Icon
  ariaLabel: string
  readOnly: boolean
  toggleAction: () => void
}

const DeleteConfigurationButton = ({
  defaultIcon,
  ariaLabel,
  readOnly,
  toggleAction,
}: DeleteConfigurationButtonProps) => {
  const onClick = () => {
    toggleAction()
  }
  return (
    <Tooltip aria-label={ariaLabel} direction="sw" noDelay>
      <IconButton icon={defaultIcon} variant="invisible" aria-label={ariaLabel} onClick={onClick} disabled={readOnly} />
    </Tooltip>
  )
}

export interface DeleteConfigurationItemProps {
  // these props are snake case because they are coming directly from rails
  is_fixed: boolean
  is_outdated: boolean
  category: string
  created_at: string
  tool_name: string
  readOnly: boolean
  toggleAction: () => void
  showTool?: boolean
}

export const DeleteConfigurationListItem = ({
  is_fixed,
  category,
  created_at,
  tool_name,
  readOnly,
  toggleAction,
  showTool,
}: Omit<DeleteConfigurationItemProps, 'is_outdated'>) => {
  const IconComponent = is_fixed ? ShieldCheckIcon : ShieldIcon
  return (
    <div className={styles.listItem}>
      <IconComponent className={clsx(is_fixed ? styles.iconDone : styles.iconSuccess)} />
      <div className={styles.contentColumn}>
        <Heading as="h5" className={styles.heading}>
          {`${category || 'API Upload'} ${showTool ? `(${tool_name})` : ''}`}
        </Heading>
        <p className={styles.subtleText}>
          Last updated <RelativeTime datetime={created_at} tense="past" />
        </p>
      </div>
      <div>
        <DeleteConfigurationButton
          defaultIcon={TrashIcon}
          ariaLabel={'Delete configuration'}
          toggleAction={toggleAction}
          readOnly={readOnly}
        />
      </div>
    </div>
  )
}
